// Generic fetch -> propose loop. The skill body is a STATEMENT body (no `export
// default`); the executor wraps it as (async function(args, context){ <code> }).
// callProvider is POSITIONAL: callProvider(provider, method, path, body?) where
// `provider` is the required tool's NAME ('generic_api') — the dispatcher resolves
// it to the tool's credentialRef server-side and injects the vaulted API key. No
// providerRef arg needed. propose.entity REQUIRES `title` (not `name`) and routes
// the write through checkPermissionOrPropose.
const path = args.path || '/records';
const profileSlug = args.entityProfile || 'note';
const res = await callProvider('generic_api', 'GET', path);
const data = res && res.body !== undefined ? res.body : res;
const records = Array.isArray(data)
  ? data
  : (data && Array.isArray(data.data) ? data.data : (data && data.records) || []);
let proposed = 0;
for (const record of records) {
  await propose.entity({
    profileSlug,
    title: String((record && (record.name || record.title || record.id)) || 'record'),
    properties: record,
  });
  proposed++;
}
return { proposed };
